// verify-result — the server is the source of truth for ranked results (T-15).
//
// POST {id, secret, result_id, actions}      (id+secret = the player's identity from localStorage 'rr-player', as for every rr_* RPC)
//   1. Engine: the exact client engine, pinned by SHA-256 in engine_pin.js (generated by tools/build-edge.mjs). Loaded once per
//      instance from the live game site (RR_ENGINE_BASE_URL, default GitHub Pages — i.e. literally the code the players run) or
//      from an `engine_bundle` string in the request (bootstrap/tests). Code that does not hash to the pin is never executed.
//   2. Postgres (SUPABASE_DB_URL, inside the function only): game.auth(id, secret); the result row must belong to the player and be
//      finished. The replay config (mode, world, character, seed, month limit) is derived from the SERVER row exactly as
//      rr_begin handed it out — nothing of it comes from the client.
//   3. E.replay(cfg, actions) → compare with the claim stored by rr_finish (status, months, passive, expenses, net worth, stars,
//      progress). Match ⇒ the REPLAYED numbers are written and verified = true. Mismatch / impossible log ⇒ claim kept for audit,
//      verified = false + verify_error (flagged; sorted last once migration t15b is applied).
//   Until migration 20261120_t15_verify_result.sql is applied the function runs in DRY-RUN mode: same checks and answer, `stored:false`.
// GET → health. verify_jwt = false on purpose: players have no Supabase auth session; the function authenticates them itself.
import postgres from 'npm:postgres@3.4.5';
import { ENGINE_SHA256, ENGINE_FILES, WORLD_PACKS } from './engine_pin.js';
import { loadEngine, loadWorldPack } from './engine_loader.js';
import { parseRequest, verifyGame, sha256Hex, clientEngine, VerifyError, MAX_BODY, MAX_BUNDLE, MAX_PACK, packFor } from './verify_core.js';

const ENGINE_BASE = (Deno.env.get('RR_ENGINE_BASE_URL') ?? 'https://orikenenb-lgtm.github.io/rat-race-game/js/').replace(/\/?$/, '/');
const MAX_ATTEMPTS = 5;            // stored mode: verification attempts per result

const CORS = {
  'Access-Control-Allow-Origin': '*', // no cookies / ambient credentials: auth is the secret in the body
  'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Max-Age': '86400',
};
const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });

// ---------------------------------------------------------------- database
let sqlConn: ReturnType<typeof postgres> | null = null;
const db = () => (sqlConn ??= postgres(Deno.env.get('SUPABASE_DB_URL')!, { prepare: false, max: 2, idle_timeout: 20, connect_timeout: 10 }));
let colsAt = 0; let fullMode = false;
async function storeMode(): Promise<boolean> {          // are the T-15 columns there? re-checked every minute (no redeploy needed)
  if (Date.now() - colsAt < 60_000) return fullMode;
  const [r] = await db()`select count(*)::int as n from information_schema.columns where table_schema = 'game' and table_name = 'results'
    and column_name in ('verified','verify_error','actions_hash','verified_at','verify_attempts','verified_result')`;
  fullMode = r.n === 6; colsAt = Date.now(); return fullMode;
}
const pgCode = (e: unknown) => String((e as any)?.message ?? '');

// ---------------------------------------------------------------- engine (cached per instance)
let engineMod: any = null; let engineSource = ''; let siteTried = 0;
async function canonicalFromSite(list: Record<string, string> = ENGINE_FILES, entry = 'engine.js'): Promise<string> {
  const files: Record<string, string> = {};
  await Promise.all(Object.keys(list).map(async (p) => {
    const r = await fetch(ENGINE_BASE + p, { signal: AbortSignal.timeout(8000) });
    if (!r.ok) throw new Error(`${p}: HTTP ${r.status}`);
    files[p] = await r.text();
  }));
  const sorted: Record<string, string> = {}; for (const k of Object.keys(files).sort()) sorted[k] = files[k];
  return JSON.stringify({ entry, files: sorted });  // same canonical text as tools/build-edge.mjs bundleText()
}
let coreText = '';
async function useBundle(text: string, source: string) {
  if (text.length > MAX_BUNDLE || await sha256Hex(text) !== ENGINE_SHA256) return false; // never execute unpinned code
  engineMod = await loadEngine(text); engineSource = source; coreText = text; return true;
}
// worlds wave 0: a lazy world's pinned pack (world file + mechanic modules), loaded on top of the core for the rows of that world only
const packTried: Record<string, number> = {};
async function worldPack(E: any, worldId: string, reqPack?: unknown) {
  const pin = packFor(worldId, WORLD_PACKS) as any; if (!pin || E.isLoaded(worldId)) return;
  const use = async (text: string) => { if (text.length > MAX_PACK || await sha256Hex(text) !== pin.sha256) return false; await loadWorldPack(E, coreText, text); return true; };
  if (typeof reqPack === 'string' && await use(reqPack)) return;
  if (Date.now() - (packTried[worldId] ?? 0) > 60_000) {
    packTried[worldId] = Date.now();
    try { if (await use(await canonicalFromSite(pin.files, pin.entry))) return; } catch (e) { console.warn('pack from site:', worldId, String(e)); }
  }
  throw new VerifyError('engine_unavailable', 503);
}
async function engine(reqBundle?: unknown) {
  if (engineMod) return engineMod;
  if (typeof reqBundle === 'string' && await useBundle(reqBundle, 'request')) return engineMod;
  if (Date.now() - siteTried > 60_000) {                    // the live site may not carry this engine yet: retry at most once a minute
    siteTried = Date.now();
    try { if (await useBundle(await canonicalFromSite(), 'site')) return engineMod; } catch (e) { console.warn('engine from site:', String(e)); }
  }
  throw new VerifyError('engine_unavailable', 503);       // not the player's fault: nothing is stored, no attempt is used
}

// ---------------------------------------------------------------- per-player throttle (per instance; stored mode also caps attempts per result)
const recent = new Map<string, number[]>();
function throttle(id: string) {
  const now = Date.now(); const l = (recent.get(id) ?? []).filter((t) => now - t < 60_000);
  if (l.length >= 10) throw new VerifyError('rate_limited', 429);
  l.push(now); recent.set(id, l); if (recent.size > 5000) recent.clear();
}

const ROW = (tx: any, q: any) => tx`select r.status, r.world, r.profession, r.months, r.passive, r.expenses, r.net_worth,
    r.stats->'progress' as claim_progress, r.stats->'stars' as claim_stars,
    case when jsonb_typeof(r.stats->'actions') = 'array' then r.stats->'actions' end as stats_actions,
    case when r.challenge_id is not null then 'challenge' when r.weekly_key is not null then 'weekly'
         when r.daily_key is not null then 'daily' else 'unknown' end as mode,
    case when r.challenge_id is not null then (select c.seed from game.challenges c where c.id = r.challenge_id)
         when r.weekly_key is not null then abs(hashtext('ratrace-' || r.weekly_key))::bigint
         when r.daily_key is not null then abs(hashtext('ratrace-daily-' || r.daily_key))::bigint end as seed,
    case when r.daily_key is not null then 24 end as max_months,
    r.daily_key::text as daily_key,
    case when r.weekly_key is not null then to_char(to_date(r.weekly_key, 'IYYY-"W"IW'), 'YYYY-MM-DD') end as weekly_start,
    (select to_char(c.created_at at time zone 'Asia/Jerusalem', 'YYYY-MM-DD') from game.challenges c where c.id = r.challenge_id) as challenge_day,
    to_char(coalesce(r.finished_at, now()) at time zone 'Asia/Jerusalem', 'YYYY-MM-DD') as finished_day
  from game.results r where r.id = ${q.resultId}::uuid and r.player_id = ${q.id}::uuid`;

async function handleVerify(req: Request, body: any) {
  const q = parseRequest(body);
  const sql = db();
  // 1. authenticate FIRST (cheap) — nothing else (engine load, replay) happens for unauthenticated callers
  try { await sql`select game.auth(${q.id}::uuid, ${q.secret})`; }
  catch (e) { if (pgCode(e) === 'unauthorized') throw new VerifyError('unauthorized', 401); throw e; }
  throttle(q.id);                                                        // per instance; the stored mode also caps attempts per result
  const full = await storeMode();
  const [row] = await ROW(sql, q);
  if (!row) throw new VerifyError('result_not_found', 404);             // also: somebody else's result
  if (row.status === 'playing') throw new VerifyError('not_finished', 409);
  let state = { verified: null as boolean | null, attempts: 0 };
  if (full) {
    const [v] = await sql`select verified, verify_attempts from game.results where id = ${q.resultId}::uuid`;
    state = { verified: v.verified, attempts: v.verify_attempts };
  }
  if (state.verified === true) {
    return json(200, { ok: true, verified: true, already: true, stored: true, result: { status: row.status, months: row.months,
      passive: row.passive, expenses: row.expenses, netWorth: row.net_worth, stars: row.claim_stars, progress: row.claim_progress } });
  }
  if (full && state.attempts >= MAX_ATTEMPTS) throw new VerifyError('rate_limited', 429);
  const actions = q.actions ?? (Array.isArray(row.stats_actions) ? row.stats_actions : null);
  if (!actions) throw new VerifyError('no_actions', 422);
  // 2. engine (503 = not the player's fault: nothing stored, no attempt used)
  const E = await engine(body.engine_bundle);
  await worldPack(E, row.world, body.world_pack);       // worlds wave 0: core + the played world's pack only (CPU and MAX_BUNDLE stay per world)
  // 3. replay + compare
  const t0 = performance.now();
  const out = verifyGame(E, row, actions);
  const ms = Math.round(performance.now() - t0);
  const r = out.result;
  const detail = { engine: ENGINE_SHA256, ms, client: clientEngine(req.headers.get('user-agent')), cfg: out.cfg, result: r,
    diff: out.diff, source: q.actions ? 'request' : 'stats', ...(out.rulesFallback ? { rulesFallback: true } : {}) };
  // 4. store (guarded: never overwrites a verified row, never touches a row that is still playing)
  let stored = false;
  if (full) {
    const hash = await sha256Hex(JSON.stringify(actions));
    const u = out.ok
      ? await sql`update game.results set status = ${r.status}, months = ${r.months}, passive = ${r.passive}, expenses = ${r.expenses},
            net_worth = ${r.netWorth}, stats = coalesce(stats, '{}'::jsonb) || ${sql.json({ progress: r.progress, stars: r.stars })},
            verified = true, verify_error = null, actions_hash = ${hash}, verified_at = now(), verified_result = ${sql.json(detail)},
            verify_attempts = verify_attempts + 1
          where id = ${q.resultId}::uuid and player_id = ${q.id}::uuid and status <> 'playing' and verified is not true`
      : await sql`update game.results set verified = false, verify_error = ${out.error.slice(0, 500)}, actions_hash = ${hash},
            verified_at = now(), verified_result = ${sql.json(detail)}, verify_attempts = verify_attempts + 1
          where id = ${q.resultId}::uuid and player_id = ${q.id}::uuid and status <> 'playing' and verified is not true`;
    stored = u.count === 1;
  }
  console.log(JSON.stringify({ result: q.resultId, verified: out.ok, error: out.ok ? null : out.error, ms, n: actions.length, stored }));
  return json(200, out.ok
    ? { ok: true, verified: true, stored, result: r }
    : { ok: true, verified: false, stored, error: out.error.split(':')[0], detail: out.error, result: r });
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
  try {
    if (req.method === 'GET') {
      // health never loads anything (no work for anonymous callers): engineLoaded = this instance already has the pinned engine
      return json(200, { ok: true, engine: ENGINE_SHA256, packs: Object.fromEntries(Object.entries(WORLD_PACKS).map(([k, v]: [string, any]) => [k, v.sha256])), engineLoaded: !!engineMod, engineSource: engineSource || null,
        store: await storeMode().catch(() => null) });
    }
    if (req.method !== 'POST') return json(405, { ok: false, error: 'method_not_allowed' });
    const len = +(req.headers.get('content-length') ?? 0);
    if (len > MAX_BODY) return json(413, { ok: false, error: 'too_big' });
    const text = await req.text();
    if (text.length > MAX_BODY) return json(413, { ok: false, error: 'too_big' });
    let body: any; try { body = JSON.parse(text); } catch (_e) { return json(400, { ok: false, error: 'bad_json' }); }
    return await handleVerify(req, body);
  } catch (e) {
    if (e instanceof VerifyError) return json(e.status, { ok: false, error: e.code });
    console.error('verify-result failed', String((e as Error)?.stack || e));
    return json(500, { ok: false, error: 'server_error' });
  }
});
